  VALUES 
    (703::BIGINT, 'Jason es de los mejores profes de CE, y se ve bien reflejado en el curso de Operativos. Da gusto ir a sus clases, se lleva bien con los estudiantes, y siempre se asegura de que todos entendieron. Los exámenes y proyectos son difíciles, pero nunca son cosas que no se vieron en clase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-18T00:00:00+00:00'::TIMESTAMPTZ, '471ac24f7a8ae970d1700e4870593c7389dd2617eaca9aa877b93f1833092561'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'Jason es simplemente un profesor excelente, el curso es pesado pero él lo hace muy divertido y llevadero, califica duro pero se aprende demasiado y le importa que los estudiantes entiendan y disfruten el curso, simplemente matricule con él porque es un profesor ESPECTACULAR.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'd564081e6e2c25a15c51a670f5068575f97d2b54eef01ecf1e5d5265066777fe'::TEXT, ARRAY[2963]::BIGINT[]),
    (703::BIGINT, 'De los mejores profes en la escuela, las clases son super entretenidas, eso sí, no regala el curso, el quiere que usted aprenda y entienda bien, de problema puede tener que cuesta que responda mensajes, entienda bien que hace en los proyectos o lo agarra de piñata'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, '4b2b9b5c3b9b04318507da31779dfbf947a7b49fc0481416c80f4fae2f351400'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'Excelente profe, el curso es bastante pesado por el proyecto pero es lograble, matriculen con él.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, '7b5e251e26f69efb46a94f909acb4843a8d5c2838addb73331cf5f4f338c7f1e'::TEXT, ARRAY[2963]::BIGINT[]),
    (703::BIGINT, 'Es un excelente profe y con explicaciones super claras. Deja proyectos complejos y exige un buen rendimiento del estudiante pero nada imposible. El curso se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '134e37315aa8b2b829c8d7b38d6309350e750df05eed00af58529eb5b0e68da1'::TEXT, ARRAY[2979]::BIGINT[]),
    (703::BIGINT, 'Llevé solo un curso con él, enseña para ser eficiente en la calle entonces califica duro, deja mucha práctica y si la lleva al día, pasa fácil, proyectos duros pero prometen mucho. Es buena persona, inteligente y todo le apasiona entonces fijo aprende cosas demás.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-18T00:00:00+00:00'::TIMESTAMPTZ, '15ec4d0fe321b9e0b0fd0876b7c5772e694d0588d8ce9b50d695c16d3f40ebd2'::TEXT, ARRAY[2511, 2961]::BIGINT[]),
    (703::BIGINT, 'Si tiene la oportunidad de llevar este curso con Jason no se va a arrepentir, él le explica a uno el por qué de los circuitos y de los aparatos que se usan en el lab. Los quices son sencillos, y no califica duro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2025-07-09T00:00:00+00:00'::TIMESTAMPTZ, 'e4890c1b9d4f67345c2a11d9523fcd7c4e933fbb98542481363014d19bd38da0'::TEXT, ARRAY[2968]::BIGINT[]),
    (703::BIGINT, 'profe demasiado buena nota, super comprensivo con los estudiantes, clases muy dinamicas y buenas, deja practicas utiles, buen material de estudio, ayuda mucho a los estudiantes, el material que da, es el que sale en el en examen, sin duda una gran eleccion en todo sentido'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'bdadb9a3c815e86a3e5de9050092760254b837ee81e9ab21f0b1d96f367920f1'::TEXT, ARRAY[2511, 2961]::BIGINT[]),
    (703::BIGINT, 'El mejor profesor de la escuela de computadores. Explica súper claro y es muy divertido en clases, incorpora a los estudiantes en sus métodos de enseñanza y vuelve la clase muy dinámica. Ayuda bastante para los proyectos y en dudas. Full full recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes']::TEXT[], '2025-06-14T00:00:00+00:00'::TIMESTAMPTZ, '895e1019a71e48a3e29bdf289fac8e5e4568157282ba5ffc282f76028ebd640f'::TEXT, ARRAY[2961]::BIGINT[]),
    (703::BIGINT, 'Definitivamente de los mejores profesores que puede elegir, ayuda bastante al estudiante, dan puntos extras y sus clases son divertidas y excelentes. Califica duro pero siempre va a procurar ayudar para que pueda recuperar puntos. No dude en matricular con él porque va a aprender demasiado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-05-28T00:00:00+00:00'::TIMESTAMPTZ, '810e7a48b52a9575b068c37005d75d88205c192873aa19d283b37fead357af00'::TEXT, ARRAY[2961]::BIGINT[]),
    (703::BIGINT, 'Es posiblemente el único profesor de Computadores al que le importa hacer bien su trabajo. Muy bueno, explica muy bien, hace las clases muy amenas y con un ambiente tuanis. Eso sí, a como explica, califica. Así que si usted es mediocre, este no es el profesor para usted. Recomendado 20/10'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Inspirador', 'Brinda apoyo']::TEXT[], '2025-03-11T00:00:00+00:00'::TIMESTAMPTZ, '4843e918617352076976aeddf375ceced45a4f18010d96ef1b857fe0fa3dc4a4'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'Siempre es un placer llevar un curso con Jason 500/10 de profe. Califica justo tirando a duro, hay que saber defender los proyectos, el exámen es fácil si puso atención en clase pregunte cuando no entiende. Los proyectos son grandes es importante tener un buen grupo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '8e9bc35572767f68828925c511d41a77e2270a7666f3472f23b57677814fb069'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '7cfe9b1d3d5f4bc334cba5e7209f93f47ae07da3207f6275e3e7ac57cbef7b68'::TEXT, ARRAY[2961]::BIGINT[]),
    (703::BIGINT, 'Es muy buen profe, se nota que le gusta enseñar y procura que todos aprendan'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'e47462435494e542fa0d40f36e33548845ee8b96023ed3fa576fb0272521b49b'::TEXT, ARRAY[2511]::BIGINT[]),
    (703::BIGINT, 'Es un gran profe, es estricto a la hora de calificar, pero muy flexible a su vez. Los labs pueden ser tediosos pero siempre que se requiere su ayuda el la da.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '1146ae670a6c60a54ff7b8abffaddbdea4e51f9fc230bbbe7322991342242995'::TEXT, ARRAY[2968]::BIGINT[]),
    (703::BIGINT, 'Excelente profesor, esta era la segunda vez que llevaba el curso e iba muy desmotivado pero logró que me volviera a interesar por la carrera. Deja bastantes practicas y en clases hace ejemplos bastante rudos pero los explica de manera excelente para que todos comprendan'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-07-30T00:00:00+00:00'::TIMESTAMPTZ, '2b009acade3b65abd4e172e89db159e86d22bf515c8b2166e198d1d362c5dc21'::TEXT, ARRAY[2511]::BIGINT[]),
    (703::BIGINT, 'Es un profesor que se preocupa por sus estudiantes, ya que les brinda el apoyo necesario, explica bien la materia y deja bastante practicas para reforzar lo visto en clase.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'fc8e6d9ea08941044a7cfb38b8a19c581fc634be5e2e2ef697e97b2034b4906d'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (703::BIGINT, 'Es muy buen profe, sabe bien de la materia. Busca ayudar a los estudiantes a entender bien los contenidos del curso y no hace las clases aburridas. Los exámenes son parecidos a las prácticas que deja. El curso es pesado por los proyectos que dejan, pero sí se logra'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '4c2975e1685d2e42f596f4a702ad5367db45c7a310df375e80d1edaa333f0f7a'::TEXT, ARRAY[2513]::BIGINT[]),
    (703::BIGINT, 'Es muy buen profe, sabe bien de la materia. Busca ayudar a los estudiantes a entender bien los contenidos del curso y no hace las clases aburridas. Los exámenes son parecidos a las prácticas que deja.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5af6be9da450be6e02f8d53abe8c50a8fa15caa1d1431bfa03662a9852416f83'::TEXT, ARRAY[2511]::BIGINT[]),
    (703::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2023-04-14T00:00:00+00:00'::TIMESTAMPTZ, '85b50b71bd26b07657d4fc21c6a42bfdc084c037615d832b16aad9e4f642a781'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (703::BIGINT, 'Explica muy bien, los repasos que realiza son de mucha ayuda, si hacen los laboratorios bien se pasa, es muy comprensivo pero se debe de llevar algo bien hecho y dominar la materia'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'd03ace36670e7867dfdf91dfbf77235e786043aa1751ff5a067c66ff89241c52'::TEXT, ARRAY[2971]::BIGINT[]),
    (703::BIGINT, 'Es un excelente profesor, explica muy bien y se aprende demasiado en el curso. Califica justo tirando a duro, exige bastante es necesario leer la retroalimentación. El curso es medio complicado, pero si le dedica el tiempo necesario pasa fácil y el profe apoya mucho; lleve el curso al día.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'b019cf989248e9c61fe668040aa00d674b82e0e14e8e05776a0fc450aa18021c'::TEXT, ARRAY[2971]::BIGINT[]),
    (703::BIGINT, 'El profe es buena gente, muy paciente, aunque la asistente se pasa revisando los quices'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2022-09-22T00:00:00+00:00'::TIMESTAMPTZ, '92a7a4bcc8f8c87a18743eb027fcddea521cdb2040d55d1181f498bec0df3ee5'::TEXT, ARRAY[2968]::BIGINT[]),
    (703::BIGINT, 'No es un buen profesor. Clases muy largas, su actitud es contradictoria y no ayuda al estudiante, más bien toma decisiones que lo perjudican. Da lastima que siga en la carrera, porque arruina lo que podría ser un muy buen curso. Si hay otra opción, tómela. Si no, agárrese...'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '4570c4934f17df40c89d2b4c67c7b4607db95d96945b7982fc9ed4094a3bc0c1'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'Es buen profe, es flexible con las entregas, aunque en ocasiones se pone en varas. Los proyectos son sencillos, si va a consulta le ayuda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2022-05-10T00:00:00+00:00'::TIMESTAMPTZ, 'c76cd2f700517a017965b63af8f66df05dcd0a731e28d71e34469ad0c2b177ea'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'Es buen profe, se pone en los zapatos de los estudiantes. Las tareas morales ayudan en los examenes'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-09-21T00:00:00+00:00'::TIMESTAMPTZ, 'c10070608e83ce5d0c5bb5516a708a2f8bca96599a0d5fd272bcc202f5247e30'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'Lleva 2 años dejando las mismas tareas mal planteadas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-16T00:00:00+00:00'::TIMESTAMPTZ, 'b7138e806716669e39db7f472df2b11c75fe2f7912a0fd7b6fe74d8a4879aa36'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'Clases largas y aburridas, solo llega a leer las presentaciones. Las 2 tareas programadas son enormes y solo valen 5% c/u, absurdo. Si pueden, no metan con él.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-09-01T00:00:00+00:00'::TIMESTAMPTZ, 'f4e7a5816268380e830b146b56eb0b9114dec5bb314d34f6454408aa775b1e51'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'No sabe nada de la materia. Dice los conceptos al revés y pierde tiempo explicando materia que se ve en los cursos de teoría que de paso la explica mal. Parece que quiere quedar a los estudiantes además cree que no se equivoca.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '3b54b31002707b12c927a2dfe090524f61c330c86e2333b38c5c37a310e99479'::TEXT, ARRAY[2971]::BIGINT[]),
    (703::BIGINT, 'Al inicio del curso se hacen 2 tareas,que literalmente son 2 progras más que solo valen un 5% cada una,seguro él pensó que era una idea fenomenal.Hablar con este mae es rarísimo uno le dice algo y el mae entiende otra cosa, era como hablar con un mae todo cerrado y aparte él cree que no se equivoca.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '814367ea216d06b6e8b1f9d3c30bc94166e27acd2eeb331b01eca7685d4fad4c'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'SI HAY OTRA OPCIÓN, NO LLEVE CON JASON. Él no sabe la materia, por ende no sabe ni lo que está pidiendo en los proyectos. Se inventa los requisitos el día de la entrega de los trabajos. No se entienden los proyectos. No se aprende nada. Super aburrido y cae mal. Deja mil trabajos y todos chocan.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'ea90d98bd2aef5794d289f88f11821539141a0a9b1050ba6a3b7d816a6272559'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'Las clases son largas y monótonas, deja demasiadas tareas que chocan entre ellas y son muy largas y complejas. El profe se pone en muchas varas para mover o revisar trabajos. Entrega notas hasta el puro final. Lastimosamente es el único profe queda el curso, si hay otro profe dele con el otro profe'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '08dc40c5053c2734090f650d54be7774d42b832b12985a112f8b2ecdce2379e8'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'Es mejor evitar este profe, es nuevo y casi no sabe nada'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5d1f229f4076c67525323264aa2e47a94586614538cda7791531dd8d2d14edfe'::TEXT, ARRAY[2968]::BIGINT[]),
    (703::BIGINT, 'Se aprende bastante de systemverilog y a usar la fpga. El profe ayuda con los proyectos pero hay muchas cosas que aprender por cuenta propia.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, '88b1573d19156a5cadd94b2437a544a4472dfb0de9e02bee6b75c74ea74806df'::TEXT, ARRAY[2971]::BIGINT[]),
    (703::BIGINT, 'Es un profesor nuevo, no tiene nada de experiencia laboral, cosa que es muy importante en una carrera como esta. No utiliza ningún material de apoyo para las clases de Introducción a la programación, y no explica tan a profundidad como los demás profesores del mismo curso. No lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2020-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'f1fc3642e615511839388084fd653d3c1093852250e63e655bac01691cbbe777'::TEXT, ARRAY[2511]::BIGINT[]),
    (703::BIGINT, 'Clases largas y curso duro por la naturaleza del mismo. Si pone atención puede aprender mucho. Si es bueno programando y pregunta las cosas que no tenga claras puede sacar perfectamente un 100 en las progras, aunque sean algo duras, pero nada que no salga.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2020-10-07T00:00:00+00:00'::TIMESTAMPTZ, 'fa09481ab84bc28443827466777d2550aef920eae9b6cf84a05bd7b95874d7dd'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'El profe es súper bueno para dar los cursos iniciales de carrera, esto hace que el estudiante se motive y le ponga al curso, además es egresado de la carrera y eso motiva aún más a seguir con el curso, el profe repita todas las veces que sea necesario, en la modalidad virtual se adapto muy bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2020-08-27T00:00:00+00:00'::TIMESTAMPTZ, 'fdcb4c06276d134c47c6d257844524979fed85a54dc400f77380acda1f54fa94'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (703::BIGINT, 'Excelente profesor para iniciar en la carrera. Enseña con claridad, da ejercicios para comprender muchos mejor la materia, los examanes no son dificiles. Ayuda bastante a los alumnos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '72eedc3845b22b23db3b5a2aefb1ef8d53da9f7990d0e97254144d9b69bda08c'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (703::BIGINT, 'Es un excelente profe para estudiantes de primer ingreso, motiva al estudiante a enamorarse de la carrera. En cuanto a la facilidad, la calificación es media pero es por los cursos en si, no por el profe. No dude en matricular con él si tiene la oportunidad!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '7e29fd0e2a98d87709629108740fd2d6fac670998c5188045337f1af89068074'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (703::BIGINT, 'Es un excelente profesor, además de ser un egresado reciente de la carrera, por lo que tiene muy presente el "sentimiento de ser estudiante", ayuda bastante, tiene buen dominio de los temas, es demasiado buena nota como profe y como persona, se preocupa por los estudiantes y las clases son muy ak7'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '54659d9d8cd19ea456a3f05dbfc9113dde5fd8ddbed6628d0cac443fefca98eb'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (703::BIGINT, 'Es bueno y se esfuerza. Al final el curso lo pasan quienes merecen pasarlo. MUCHOS MUCHOS trabajos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Brinda apoyo']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '4aa6975508581e1b14ea1faade2c1499623f67a13621ebb17197843a9039450f'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'Excelente profesor, muy buena bienvenida al TEC y explica y conoce los temas muy bien. Es graduado de la carrera y por esto también da consejos útiles sobre los cursos futuros y consejos para el TEC en general. Muy buena gente y ejemplo a seguir.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'a4cde2e30c33d7d43b1987f5937d567232879ff8e2dc3aea9c6459d2b921a031'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (703::BIGINT, 'Su curso es bastante ameno, deja proyectos divertidos e inspiradores. Lo prepara a uno para los cursos siguientes, fue estudiante del TEC y es bastante comprensivo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '32ebc0357c899ebf01d296be080688f1ddecc6b972a0de3d4555ed05b826415c'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (703::BIGINT, 'Super buen profe, explica muy bien y lo prepara a uno para los exámenes y proyectos. 10/10'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-07-21T00:00:00+00:00'::TIMESTAMPTZ, '801f51276234d3aa923202c7f358201630d2cb63965a41bae7be582736ad2b9c'::TEXT, ARRAY[2511, 2513]::BIGINT[]),
    (703::BIGINT, 'Las clases son largas, pero dada la materia es entendible. El problema son las tareas/proyectos son bastante pesadas.... una completa parida por apenas 5%'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-05-27T00:00:00+00:00'::TIMESTAMPTZ, '8b4faf8e25d52e1dd8e3300d4cb5a4328480484638c29a2118de0852fe9febc1'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'Un profesor que pese a haber sido estudiante de la carrera trata de poner el curso lo mas duro posible, hace muchas preguntas en clase seleccionando a un estudiante y califica duro, nada recomendado'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-05-17T00:00:00+00:00'::TIMESTAMPTZ, '292e87325675c8d5b197dbb263a02cc69a3d9fa67739fc7a313da3c61dbb7d75'::TEXT, ARRAY[2983]::BIGINT[]),
    (703::BIGINT, 'Es un profe nuevo, lo que se evalúa es lo que se ve en clase.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-03-01T00:00:00+00:00'::TIMESTAMPTZ, '9ed90391594dc0d76fc246c7fb9991140fd1fda7f85033683360cf2744f7ef43'::TEXT, ARRAY[2983]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
